import{_ as a,c as t,o as i,ae as o}from"./chunks/framework.2MVDia4S.js";const u=JSON.parse('{"title":"Production readiness","description":"","frontmatter":{},"headers":[],"relativePath":"production-readiness.md","filePath":"production-readiness.md"}'),r={name:"production-readiness.md"};function n(s,e,d,l,c,h){return i(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="production-readiness" tabindex="-1">Production readiness <a class="header-anchor" href="#production-readiness" aria-label="Permalink to &quot;Production readiness&quot;">​</a></h1><p>The v0.3 architecture is production-oriented; the current alpha is not production-ready. A release may remove that label only when evidence for every required gate is linked from this page.</p><h2 id="required-gates" tabindex="-1">Required gates <a class="header-anchor" href="#required-gates" aria-label="Permalink to &quot;Required gates&quot;">​</a></h2><ul><li>[ ] 4+ validator multi-host network with independent ELs and datadirs</li><li>[ ] Mixed-client and per-fork continuous compatibility matrix</li><li>[ ] Byzantine proposer, invalid payload, equivocation, and malformed RLP tests</li><li>[ ] Network partition, delayed Engine API, process kill, disk-full, and <code>FinalizeBlock</code>/<code>Commit</code> crash tests</li><li>[ ] Validator bootstrap/replacement and ABCI snapshot state-sync procedure</li><li>[ ] Coordinated fork, protocol, binary, and validator-set upgrade runbooks</li><li>[ ] Sustained throughput and worst-case payload resource benchmarks</li><li>[ ] Metrics and alerts for lag, sync, rejection, RPC failure, recovery, disk, memory, and consensus liveness</li><li>[ ] Backup/restore, key isolation, JWT rotation, and incident response drills</li><li>[ ] Threat model and independent security audit with resolved findings</li><li>[ ] Reproducible builds, SBOM, signed artifacts, and rollback rehearsal</li></ul><h2 id="evidence-completed-in-the-alpha" tabindex="-1">Evidence completed in the alpha <a class="header-anchor" href="#evidence-completed-in-the-alpha" aria-label="Permalink to &quot;Evidence completed in the alpha&quot;">​</a></h2><ul><li>[x] Four validators with independent Geth datadirs agree on CometBFT block hashes, app hashes, Ethereum block hashes, and transaction receipts on one Docker host.</li><li>[x] The network continues committing with one complete validator stack stopped, and the stopped CometBFT/EthBFT/Geth stack catches up after restart.</li></ul><p>These checks deliberately do not close the 4+ validator production gate: that gate requires separate hosts and the broader failure matrix above.</p><h2 id="deployment-invariants" tabindex="-1">Deployment invariants <a class="header-anchor" href="#deployment-invariants" aria-label="Permalink to &quot;Deployment invariants&quot;">​</a></h2><p>Engine API is never public. Each validator&#39;s EthBFT process is the only forkchoice authority for its dedicated EL. Protocol configuration, execution genesis, and CometBFT genesis are release artifacts. Readiness, not liveness, controls validator admission.</p>',9)])])}const m=a(r,[["render",n]]);export{u as __pageData,m as default};
